package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.preference.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** VM-only real Settings roundtrips with a long synthetic candidate list; no device configuration changes. */
public final class ScreenRoutesCheck extends Instrumentation {
 private Context c;private HomeActivity home;private SettingsActivity settings;private RadioScreens screen;private Map<String,?> before;private int checks;private String fixturePackage;private final StringBuilder log=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);start();}private void check(boolean ok,String name){checks++;log.append(ok?"PASS ":"FAIL ").append(name).append('\n');if(!ok)throw new AssertionError(name);}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}interface Condition{boolean ok()throws Exception;}private void until(Condition condition)throws Exception{long end=SystemClock.uptimeMillis()+22000;while(!condition.ok()&&SystemClock.uptimeMillis()<end){VmWindows.clear(this);Thread.sleep(80);}check(condition.ok(),"await condition");}private Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}private ListView list()throws Exception{return (ListView)field(screen,"list");}private void shell(String cmd)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(cmd))){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}private ActionSheet prompt()throws Exception{Field f=ActionSheet.class.getDeclaredField("active");f.setAccessible(true);ActionSheet s=(ActionSheet)((java.lang.ref.WeakReference<?>)f.get(null)).get();return s!=null&&s.dialog.isShowing()?s:null;}
 private void preference(Preference p)throws Exception{Method method=Preference.class.getDeclaredMethod("performClick",PreferenceScreen.class);method.setAccessible(true);main(()->{try{method.invoke(p,settings.getPreferenceScreen());}catch(Exception e){throw new RuntimeException(e);}});}
 private void open(boolean wifi)throws Exception{ActivityMonitor m=new ActivityMonitor(RadioScreens.class.getName(),null,false);addMonitor(m);preference(settings.findPreference(wifi?"wifi_screen":"bluetooth_screen"));screen=(RadioScreens)waitForMonitorWithTimeout(m,16000);removeMonitor(m);check(screen!=null,"settings opens dedicated "+(wifi?"Wi-Fi":"Bluetooth")+" chooser");until(()->!(Boolean)field(screen,"loading"));check((Boolean)field(screen,"wifi")==wifi,"chooser uses correct independent mode");check(!((List<?>)field(screen,"all")).isEmpty(),"real public system candidates discovered before fixture injection");Button mode=(Button)field(screen,"mode");main(()->mode.requestFocusFromTouch());android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),"routes-"+BuildConfig.VERSION_CODE+"-"+(wifi?"wifi":"bt")+"-focus.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}shot.recycle();int focusedInk=mode.getCurrentTextColor();android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(mode.getWidth(),mode.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);main(()->mode.getBackground().draw(new android.graphics.Canvas(image)));int focusedFill=image.getPixel(image.getWidth()/2,image.getHeight()/2);main(()->{try{list().requestFocusFromTouch();}catch(Exception e){throw new RuntimeException(e);}});main(()->{image.eraseColor(0);mode.getBackground().draw(new android.graphics.Canvas(image));});int restingFill=image.getPixel(image.getWidth()/2,image.getHeight()/2);image.recycle();check(focusedFill!=restingFill&&focusedInk!=mode.getCurrentTextColor(),"mode button visibly changes background and text when focus moves");}
 @SuppressWarnings("unchecked")private ArrayList<RadioScreens.Route> fixtures(boolean wifi,ComponentName component)throws Exception{ArrayList<RadioScreens.Route> choices=new ArrayList<>();for(int n=0;n<45;n++){Intent intent=new Intent(android.provider.Settings.ACTION_SETTINGS).setComponent(component).putExtra("truetv_route_fixture",(wifi?"wifi-":"bt-")+n);choices.add(new RadioScreens.Route("VM synthetic screen "+n,intent,120));}ArrayList<RadioScreens.Route> all=(ArrayList<RadioScreens.Route>)field(screen,"all");Method filter=RadioScreens.class.getDeclaredMethod("filter");filter.setAccessible(true);main(()->{all.clear();all.addAll(choices);try{filter.invoke(screen);}catch(Exception e){throw new RuntimeException(e);}});return choices;}
 private int select(int index)throws Exception{ListView l=list();main(()->{l.requestFocusFromTouch();l.setSelectionFromTop(index,70);});until(()->l.getSelectedItemPosition()==index&&l.getSelectedView()!=null);return l.getSelectedView().getTop();}
 private void testSelected()throws Exception{ListView l=list();int pos=l.getSelectedItemPosition();main(()->l.performItemClick(l.getSelectedView(),pos,pos));until(()->!screen.hasWindowFocus());until(()->{for(android.view.accessibility.AccessibilityWindowInfo window:getUiAutomation().getWindows()){android.view.accessibility.AccessibilityNodeInfo node=window.getRoot();if(window.isFocused()&&node!=null&&fixturePackage.contentEquals(node.getPackageName()))return true;}return false;});shell("input keyevent 4");until(()->prompt()!=null&&prompt().dialog.isShowing());}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"VM guard");SettingsStore store=new SettingsStore(c);before=new HashMap<>(store.data.getAll());store.data.edit().putBoolean("bt_asked",true).putBoolean("bt_count",false).remove("wifi_route").remove("bluetooth_route").commit();VmWindows.prepare(this);home=VmWindows.home(this);ActivityMonitor monitor=new ActivityMonitor(SettingsActivity.class.getName(),null,false);addMonitor(monitor);main(()->home.header.getChildAt(3).performClick());settings=(SettingsActivity)waitForMonitorWithTimeout(monitor,16000);removeMonitor(monitor);check(settings!=null&&settings.findPreference("wifi_screen")!=null&&settings.findPreference("bluetooth_screen")!=null,"both screen-selection settings are present");check(settings.findPreference("wifi_name")==null&&settings.findPreference("wifi_screen").getParent()==settings.findPreference("bluetooth_screen").getParent(),"screen settings stay together; obsolete Wi-Fi name permission row is removed");ResolveInfo resolved=c.getPackageManager().resolveActivity(new Intent(android.provider.Settings.ACTION_SETTINGS),PackageManager.MATCH_DEFAULT_ONLY);ComponentName target=new ComponentName(resolved.activityInfo.packageName,resolved.activityInfo.name);fixturePackage=target.getPackageName();check(RadioScreens.valid(c,new Intent().setComponent(target)),"fixture endpoint is a genuinely accessible system Activity");
 for(boolean wifi:new boolean[]{true,false}){String other=store.text(RadioScreens.key(!wifi),"");open(wifi);ArrayList<RadioScreens.Route> choices=fixtures(wifi,target);ListView l=list();int top=select(23);int first=l.getFirstVisiblePosition();testSelected();main(()->{try{prompt().rows.get(1).performClick();}catch(Exception e){throw new RuntimeException(e);}});until(()->l.hasFocus()&&l.getSelectedItemPosition()==23);check(Math.abs(l.getSelectedView().getTop()-top)<=2&&Math.abs(l.getFirstVisiblePosition()-first)<=1,"Choose another restores last tested row and viewport in "+(wifi?"Wi-Fi":"Bluetooth"));check(store.text(RadioScreens.key(wifi),"").isEmpty(),"unsuccessful candidate is not saved");testSelected();shell("input keyevent 4");until(()->prompt()==null&&l.hasFocus()&&l.getSelectedItemPosition()==23);check(Math.abs(l.getSelectedView().getTop()-top)<=2,"Back dismissing confirmation preserves the same row");select(28);testSelected();main(()->{try{prompt().rows.get(0).performClick();}catch(Exception e){throw new RuntimeException(e);}});until(()->screen.isFinishing()&&settings.hasWindowFocus());check(store.text(RadioScreens.key(wifi),"").equals(choices.get(28).key),"only explicitly confirmed "+(wifi?"Wi-Fi":"Bluetooth")+" route saved");check(store.text(RadioScreens.key(!wifi),"").equals(other),"other radio's route remains unchanged");screen=null;}
 main(settings::finish);settings=null;until(()->home.hasWindowFocus());final ArrayList<Intent> launched=new ArrayList<>();ActivityMonitor launches=new ActivityMonitor(){public ActivityResult onStartActivity(Intent i){if(i.getComponent()!=null&&!c.getPackageName().equals(i.getComponent().getPackageName())){launched.add(new Intent(i));return new ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};addMonitor(launches);main(()->home.header.getChildAt(5).performClick());check(!launched.isEmpty()&&launched.get(launched.size()-1).toUri(0).equals(store.text("wifi_route","")),"header launches exact saved Wi-Fi Intent");main(()->home.header.getChildAt(6).performClick());check(launched.get(launched.size()-1).toUri(0).equals(store.text("bluetooth_route","")),"header launches exact saved Bluetooth Intent");removeMonitor(launches);
 for(boolean wifi:new boolean[]{true,false}){for(boolean stale:new boolean[]{false,true}){String k=RadioScreens.key(wifi);Intent absent=new Intent().setComponent(new ComponentName("com.android.settings","com.android.settings.TrulyMissingActivity"));main(()->{SharedPreferences.Editor edit=store.data.edit();if(stale)edit.putString(k,absent.toUri(0));else edit.remove(k);edit.commit();});ActivityMonitor chooser=new ActivityMonitor(RadioScreens.class.getName(),null,false);addMonitor(chooser);main(()->home.header.getChildAt(wifi?5:6).performClick());screen=(RadioScreens)waitForMonitorWithTimeout(chooser,15000);removeMonitor(chooser);check(screen!=null,"short OK opens chooser for "+(wifi?"Wi-Fi":"Bluetooth")+" when route is "+(stale?"stale":"unset"));check((Boolean)field(screen,"wifi")==wifi,"fallback chooser uses the requested radio mode");if(stale)check(store.text(k,"").equals(absent.toUri(0)),"unavailable saved route is preserved until explicit replacement");main(screen::finish);screen=null;until(()->home.hasWindowFocus());}} ActivityMonitor alias=new ActivityMonitor(RadioScreens.class.getName(),null,false);addMonitor(alias);main(()->c.startActivity(new Intent().setComponent(new ComponentName(c.getPackageName(),c.getPackageName()+".BluetoothScreens")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));screen=(RadioScreens)waitForMonitorWithTimeout(alias,15000);removeMonitor(alias);check(screen!=null,"legacy private Bluetooth component still opens after upgrade");check(!((Boolean)field(screen,"wifi")),"legacy alias retains Bluetooth mode");result.putBoolean("passed",true);
 }catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));log.append(w);result.putBoolean("passed",false);}finally{try{ActionSheet p=prompt();if(p!=null)main(p.dialog::dismiss);if(screen!=null)main(screen::finish);if(settings!=null)main(settings::finish);if(home!=null)main(home::finish);if(before!=null){SharedPreferences.Editor e=new SettingsStore(c).data.edit().clear();for(Map.Entry<String,?> entry:before.entrySet()){Object v=entry.getValue();if(v instanceof String)e.putString(entry.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(entry.getKey(),(Boolean)v);else if(v instanceof Integer)e.putInt(entry.getKey(),(Integer)v);else if(v instanceof Long)e.putLong(entry.getKey(),(Long)v);}e.commit();}}catch(Exception e){log.append("RESTORE ").append(e);}}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
